import type { Story } from './history-types';

const primary = 'https://en.wikisource.org/wiki/The_Pictorial_Key_to_the_Tarot/Part_2';
const museum = 'https://www.metmuseum.org/perspectives/tarot-2';
type Seed = { en: Story; 'zh-CN': Story };
const story = (teaser: string, origin: string, evolution: string, symbols: [string, string][], today: string, detail: string, chinese = false): Story => ({
  teaser,
  origin: [origin],
  evolution: [evolution, chinese
    ? '这里的画面来自1909年的莱德·韦特·史密斯塔罗牌，由帕梅拉·科尔曼·史密斯绘制。韦特随后在《塔罗图解之钥》中说明自己的象征理念。画家创造的姿态、视线与空间，以及作者赋予画面的解释，都值得分别阅读：我们能在画上看见什么，与某位作者相信它代表什么，并不是同一个问题。今天的解释又为这段历史增添了新的一层。'
    : 'The illustration here belongs to the 1909 Rider–Waite–Smith deck, drawn by Pamela Colman Smith. Arthur Edward Waite explained his symbolic program in The Pictorial Key to the Tarot. Read the picture and his explanation alongside one another: a posture, an expression, or a distance between figures can do something that a list of meanings cannot. The artist’s visual choices, the author’s stated beliefs, and a present-day reader’s response are related, but they are not interchangeable kinds of evidence.'],
  symbols: symbols.map(([name, text]) => ({ name, text })),
  today: [today],
  detail,
  sources: [primary, 'https://en.wikisource.org/wiki/The_Pictorial_Key_to_the_Tarot/Part_1', museum],
});

export const historyMajor: Record<string, Seed> = {
  'major-16': {
    en: story('A building loses its crown, and a confident structure suddenly becomes a question.',
      'The Tower belongs to a historical family of tarot images involving a struck or broken building. Names and details vary between traditions, so a single explanation should not be imposed on every version. In French tarot the title Maison Dieu adds another layer of interpretive difficulty. What remains visually compelling is the failure of a structure that seemed to rise above ordinary vulnerability. Later authors repeatedly used that scene to think about pride, doctrine, and the collapse of false security.',
      'Smith makes the event dramatic: lightning strikes a high tower, a crown is thrown from the top, flames emerge, and two people fall. Waite surveys other occult explanations before favoring the breaking of a false intellectual or doctrinal structure. His interpretation is more specific than “something bad will happen.” The scene becomes an argument about what cannot continue to stand, although the suffering figures keep the image from becoming a purely comfortable metaphor.',
      [['The displaced crown', 'The top of the tower resembles a crown and is pushed away by the strike. Authority and architecture become linked in one detail. A viewer can ask whether the structure’s apparent superiority depended on an unstable claim.'], ['The lightning', 'The bright diagonal interrupts the building’s upright lines. It makes suddenness visible and draws the eye directly to the point of rupture. The picture does not establish whether a real disruption is deserved, beneficial, or predictable.'], ['The falling people', 'The two bodies give the architectural disaster a human cost. Waite discusses them while criticizing explanations he finds incomplete. Their presence matters because collapsing ideas and institutions affect lives, not only abstract systems.']],
      'Modern readings often associate the Tower with revelation, upheaval, and recognizing that an arrangement cannot continue unchanged. Its history supports a careful distinction between insight and catastrophe. Discovering a false assumption can be useful; being harmed is not automatically a necessary lesson. A grounded reading asks what needs immediate care, which belief has failed, and what more trustworthy foundation could be built after the shock.',
      'Waite focuses on a false structure of thought or doctrine. His account gives the falling tower an intellectual dimension, not just a material one.'),
    'zh-CN': story('建筑失去冠顶，原本自信的结构突然成为疑问。',
      '高塔属于塔罗中受击或破损建筑的一组历史图像。各传统名称与细节不同，不应给所有版本强加同一解释。法语名称Maison Dieu又增添了一层理解难度。持续吸引目光的是：一个仿佛高于普通脆弱性的结构竟然失效。后来的作者不断借它讨论骄傲、教义与虚假安全感的崩塌。',
      '史密斯使事件非常戏剧化：闪电击中高塔，冠状顶端被掀开，火焰出现，两人坠落。韦特比较不同神秘主义解释后，偏向虚假思想或教义结构的破裂。这比“坏事将发生”具体得多。画面讨论什么无法继续成立，受苦人物又使它不能变成完全舒适的比喻。',
      [['被掀开的冠顶', '塔顶形似王冠，被撞离原位，权威与建筑通过一个细节相连。观看者可以问，结构的优越感是否依赖不稳定的主张。'], ['闪电', '明亮斜线打断建筑竖线，让突发可见，把视线引向破口。画面没有证明现实的动荡是应得、有益或可预测的。'], ['坠落的人', '两个人体赋予建筑灾难真实代价。韦特在批评不足的解释时也讨论他们，提醒思想与制度的崩塌会影响生命，而不只是抽象体系。']],
      '今天，高塔常谈揭露、动荡与某种安排不能原样继续。历史帮助区分洞见与灾难：发现错误假设可能有用，受到伤害却不自动成为必要课程。更实际的问题是眼下需要照料什么、哪种信念失效，以及震动之后怎样建立更可靠的基础。',
      '韦特重点讨论虚假的思想或教义结构。因此，倒塌高塔具有智性层面，而不只是物质破坏。', true),
  },
  'major-17': {
    en: story('After the tower’s violence, water and an open sky offer a different kind of power.',
      'The Star is one of the celestial subjects inherited by tarot. A star can orient a viewer without depicting a worldly ruler, and later versions developed a distinctive scene of a person pouring water beneath the sky. The subject’s visual history should be distinguished from any claim that it has always meant the same thing. Hope is now an especially familiar keyword, but Waite’s own discussion shows that even influential occult writers did not agree that this simple label was sufficient.',
      'Smith places a naked figure beside water, pouring from two vessels beneath one large star and seven smaller ones. Waite describes a communication of life and spiritual gifts, and connects the figure with truth unveiled and a Kabbalistic understanding of the Great Mother. Those are his attributed interpretations. The illustration also works without mastering that vocabulary: an unarmored body, flowing water, and a broad sky create a scene of openness very different from the enclosed power of the Tower.',
      [['The two streams', 'Water goes both into the pool and onto the land. The gesture links different parts of the landscape rather than keeping all nourishment in one place. A modern reading can see renewal as something that circulates and reaches outward.'], ['The unclothed figure', 'The figure has no crown, armour, or elaborate costume. Waite associates this openness with unveiled truth. A viewer may also notice the absence of defenses, while remembering that vulnerability is meaningful only in relation to its surroundings.'], ['The large star', 'One prominent star organizes the smaller lights around it. Its scale gives the eye a point of orientation. The composition can evoke guidance without identifying a literal future destination or proving that events are arranged for the viewer.']],
      'Today the Star often supports reflection on recovery, hope, and the gradual return of trust. Its quietness matters: nothing is being conquered, and no audience is applauding. The card can make small acts of replenishment seem worthy of attention. Hope need not mean certainty that everything will work out; it can mean making room for life to continue while accepting that recovery has its own pace.',
      'Waite considers “hope” too limited as a full explanation. One of the card’s most familiar modern keywords was already being debated in its early commentary.'),
    'zh-CN': story('高塔的剧烈之后，水与开阔天空展示另一种力量。',
      '星星是塔罗继承的天体题材之一。星光可以指引目光，而无须描画世俗统治者；较后的版本发展出人在星空下倒水的特定场景。图像历史不应与“始终拥有同一意义”的说法混淆。希望是今天非常熟悉的关键词，但韦特的讨论已经说明，有影响的作者也不认为简单标签足以概括它。',
      '史密斯让赤身人物在水边持两壶倾倒，上方有一颗大星与七颗小星。韦特讨论生命与精神礼物的传递，把人物联系到揭开面纱的真理，以及卡巴拉中的伟大母亲。这些应明确归于他的解释。即使不掌握术语，无遮蔽身体、流水与天空，也能营造出与高塔封闭力量截然不同的开放感。',
      [['两道水流', '水一边进入池中，一边流向土地，把风景不同部分联系起来，而非把滋养留在一处。现代阅读可以由此看到更新的流动与向外延伸。'], ['赤身人物', '人物没有王冠、铠甲或华服。韦特把这种开放联系到无遮掩的真理；观看者也能注意到防备的缺席，但脆弱的意义仍需要环境来理解。'], ['大星', '一颗突出的星组织周围小光点，为视线提供方向。构图可以唤起指引，却没有指定现实未来目的地，也没有证明事件专为观看者安排。']],
      '今天，星星常帮助思考恢复、希望与信任的慢慢返回。它的安静很重要：没有征服，也没有观众喝彩。微小的补充与滋养因此值得留意。希望不必是事情必然顺利的确定感，也可以是在承认恢复需要时间时，给生命继续留出空间。',
      '韦特认为“希望”不足以完整解释这张牌。最熟悉的现代关键词之一，在早期评论里就已受到讨论。', true),
  },
  'major-18': {
    en: story('A path enters uncertain country under light that is bright enough to reveal, but not to clarify everything.',
      'The Moon belongs to tarot’s inherited group of celestial images. Its changing visual forms eventually include animals, water, and paired towers, building a landscape rather than simply presenting an object in the sky. That landscape makes uncertainty experiential: the viewer sees a route, yet cannot follow it to a clear destination. Later interpreters used the scene to discuss imagination, fear, and indirect knowledge. Those psychological meanings should not be projected backward as a complete account of every early Moon card.',
      'Smith shows a dog and a wolf beneath the moon, a creature emerging from water, and a path between two towers. Waite contrasts reflected light with the direct light of the Sun and interprets the animals as disturbances of the natural mind before the unknown. His language about the creature from the depths is severe and belongs to his mystical framework. A contemporary reader can study that history without accepting its judgment of instinct or the unconscious.',
      [['The dog and wolf', 'The familiar and the wild stand on opposite sides of the path. Their similar reactions complicate a simple division between safe and dangerous. The scene can prompt a question about how different parts of oneself respond to uncertainty.'], ['The emerging creature', 'A small aquatic creature approaches the land from the pool. Its threshold position echoes the larger journey into unfamiliar space. Observation gives us the movement; claims about exactly which hidden psychic force it represents are interpretations.'], ['The path and towers', 'The route passes between paired structures and continues into the distance. The towers frame an opening rather than closing it. The picture gives a direction to follow without granting the clear view that would remove all doubt.']],
      'Today the Moon often helps people talk about ambiguity, dreams, intuition, and anxiety. Its distinction between seeing and knowing is especially useful. A strong impression may be meaningful without being a reliable report of external events. A grounded reading asks what is visible, what has been assumed, and what further information would help. It can encourage patience with uncertainty without turning every fear into a warning or every dream into a prediction.',
      'Waite explicitly contrasts the Moon’s reflected light with the Sun’s direct light. The two cards form a visual conversation about different kinds of knowing.'),
    'zh-CN': story('小路在月光下通往未知：光足以照见，却未必足以解释一切。',
      '月亮属于塔罗继承的天体图像，变化中的版本逐渐包含动物、水与双塔，形成风景，而不只是天空中的物体。风景让不确定成为可以感受的经验：看得到路，却看不清终点。后来解释者用它谈想象、恐惧与间接认识，但这些心理意义不应被投射回所有早期月亮牌，充当完整历史。',
      '史密斯画出月下的狗与狼、水中爬出的生物，以及穿过双塔的小路。韦特把反射光与太阳的直接光相比，将动物理解为心智面对未知时的骚动。他对深处生物的措辞很严厉，属于自己的神秘主义框架。今天可以了解这段历史，而不必接受其对本能或无意识的评价。',
      [['狗与狼', '熟悉与野性分列路旁，却作出相似反应，使安全与危险的简单划分变得复杂。可以问自身不同部分如何回应不确定。'], ['出水生物', '小型水生生物正从池中接近陆地，它的门槛位置呼应通向陌生空间的旅程。移动是可见现象，具体代表哪种隐秘心理力量则属于解释。'], ['小路与双塔', '路穿过成对建筑延伸到远处。塔框出入口，而非封死它；画面给出方向，却没有提供能消除疑问的完整视野。']],
      '今天，月亮常帮助谈模糊、梦、直觉与焦虑。区分看见与知道尤其有用：强烈感受可以有意义，却未必可靠描述外部事件。可以问什么确实可见、什么是推断，以及需要什么资讯。耐心面对未知，不等于把所有恐惧当作警告，或把每个梦当成预言。',
      '韦特明确对比月亮的反射光与太阳的直接光。两张牌由此形成关于认识方式的视觉对话。', true),
  },
  'major-19': {
    en: story('A child rides into the open, turning illumination into a scene of unguarded life.',
      'The Sun is another longstanding celestial subject in tarot. Historical images vary, so the single child on a horse should not be treated as the only form the card has ever taken. The enduring source of its visual force is easier to recognize: sunlight makes a world visible and supports living things. Later symbolic systems developed that ordinary experience into accounts of consciousness, spiritual illumination, and restored life. The picture’s accessibility helped those meanings travel.',
      'Smith presents a naked child on a white horse, holding a red banner in front of a wall and sunflowers. Waite favors this arrangement and interprets the child as simplicity joined with a kind of spiritual wisdom. He contrasts direct solar light with the reflected light of the Moon. The result is not merely a cheerful weather scene. It is his picture of a renewed relationship between conscious life, nature, and what he understands as a higher illumination.',
      [['The child', 'The child appears exposed and confident rather than protected by ceremonial clothing. Waite’s interpretation concerns innocence transformed by wisdom, not a demand to become naive. A modern viewer can notice the difference between openness and lack of awareness.'], ['The white horse', 'The child rides without the armoured command associated with the Chariot. The animal contributes movement without making the scene look like conquest. The contrast invites different ways of imagining cooperation between human intention and bodily energy.'], ['The wall and flowers', 'The wall provides a boundary while the sunflowers rise beyond it. Their presence gives the open foreground a setting from which to emerge. A viewer can ask what kind of protection has supported growth and what is now ready for wider space.']],
      'Today the Sun often supports readings about clarity, enjoyment, and sharing what is going well. Its history offers something more nuanced than a promise that difficulty has ended. Direct light can reveal work still to do as well as reasons for gratitude. The card can invite a person to acknowledge a real success, accept warmth without embarrassment, or bring a confusing situation into a setting where it can be seen more clearly.',
      'The horse links this bright scene with other mounted figures in the deck, but the child carries no armour. Similar visual elements can produce very different emotional worlds.'),
    'zh-CN': story('孩子骑向开阔处，让光明成为不设防的生命场景。',
      '太阳也是塔罗中历史悠久的天体题材。不同历史图像并不相同，不能把骑马的单个孩子当作唯一形式。它持续拥有视觉力量的原因更容易理解：阳光使世界可见，并支持生命。后来的象征体系把这种日常经验发展为意识、精神照明与生命更新的论述，图像的易懂帮助这些意义传播。',
      '史密斯让赤身孩子骑白马、持红旗，身后是墙与向日葵。韦特偏好这种安排，把孩子解释为简单与精神智慧的结合，并将太阳直接光与月亮反射光相对照。因此它不只是天气晴朗，而是他所理解的意识、自然与更高照明之间更新的关系。',
      [['孩子', '孩子没有仪式服装保护，却显得自在而自信。韦特讨论的是与智慧相连的纯真，不是要求人天真无知。可以观察开放与缺乏觉察的区别。'], ['白马', '孩子骑马的方式不同于战车的披甲控制。动物带来运动，却没有征服感，邀请我们想象意图与身体能量的不同合作方式。'], ['墙与花', '墙形成边界，向日葵在后面升起，使开阔前景拥有出发背景。可以问哪些保护支持了成长，以及什么已经准备走向更宽空间。']],
      '今天，太阳常谈清晰、享受与分享顺利之处。历史提供了比“困难已经结束”更细致的理解：直接光既照见值得感谢的事，也照见仍需完成的工作。可以承认真实进步、坦然接受温暖，或把混乱局面带到能够看清的环境里。',
      '白马使明亮场景与牌组其他骑乘人物相联系，孩子却没有铠甲。同样的视觉元素，能够创造完全不同的情绪世界。', true),
  },
  'major-20': {
    en: story('A resurrection scene becomes a call that is heard from within.',
      'Judgement has a particularly clear relationship with Christian imagery of the resurrection and Last Judgment. An angel sounding a trumpet above people rising from graves would have been recognizable in the religious culture surrounding early tarot. This is more specific than the everyday act of judging whether someone is right or wrong. The older subject concerns an ultimate summons and a transformation of existence, which helps explain the dramatic scale of the picture.',
      'Smith retains the trumpet, banner, and rising bodies, but shows more people than the small foreground group alone. Waite says that the additional figures help resist overly narrow interpretations. He describes an inwardly heard call and a transformation answered from within. That mystical explanation does not erase the Christian scene; it reads the scene on another level. Modern interpretations of awakening and reviewing one’s life continue this movement from public religious image toward personal experience.',
      [['The trumpet', 'The instrument makes a sound visible through its position and the reactions below. It is a call rather than a conversation. A modern viewer can ask what is difficult to ignore, while avoiding the assumption that every strong feeling is an external command.'], ['The rising figures', 'Their arms and faces respond with wonder rather than a courtroom defense. The scene’s emotional energy comes from renewal and recognition. This helps distinguish the card from ordinary blame, punishment, or criticism of one’s past.'], ['The distant people', 'More figures rise beyond the foreground family. Their inclusion expands the event from an isolated private story into something shared. Waite explicitly notices this addition, giving a concrete reason to look beyond the largest figures first.']],
      'Today Judgement often helps people discuss a wake-up call, honest review, or a decision to live differently after understanding the past. The history of resurrection gives that reading a sense of possibility, while the seriousness of the summons keeps it from being casual reinvention. A useful question is what you now recognize that you cannot responsibly pretend not to know. Learning from the past need not become permanent self-condemnation.',
      'The background figures are not incidental crowd decoration in Waite’s account. He points to them as a deliberate way of broadening the card’s meaning.'),
    'zh-CN': story('复活场景成为从内心听见的召唤。',
      '审判与基督教复活及末日审判图像的关系尤其清楚。天使吹号、墓中人起身，在早期塔罗所处的宗教文化里容易辨认。这比日常判断某人对错更加具体：旧题材关乎最终召唤与存在状态的改变，也解释了画面为何具有如此宏大的尺度。',
      '史密斯保留号角、旗帜与起身的人，却在前景小群体之外画出更多人物。韦特说，增加的人物帮助抵抗过窄解释；他讨论从内在听见并回应的召唤与转变。这种神秘主义解释没有抹去基督教场景，而是在另一层阅读它。现代的觉醒与回顾人生，延续了公共宗教图像走向个人经验的过程。',
      [['号角', '通过乐器位置与下方反应，声音变得可见。它是召唤而非交谈，可以使人问什么已经难以忽视，却不必把每种强烈感觉都当成外来命令。'], ['起身的人', '人物以惊叹的姿态回应，而不是在法庭自辩。情绪能量来自更新与认知，有助于把它与普通责备、惩罚或批评过去区别开来。'], ['远处人物', '前景家庭之外还有更多人起身，使事件超出私人故事，成为共享经验。韦特明确注意到这项增加，提醒我们别只看最大人物。']],
      '今天，审判常帮助讨论警醒、诚实回顾，以及理解过去后选择不同生活。复活背景赋予这种理解可能性，召唤的严肃又使它不只是随意改头换面。可以问现在已经认清什么，不能再负责地假装不知道。向过去学习，不必变成永久自我谴责。',
      '在韦特说明中，背景人物不是随意装饰。他把它们视作主动拓宽意义的一种设计。', true),
  },
  'major-21': {
    en: story('The last numbered trump pictures completion as something alive and moving.',
      'The World occupies a high place in historical tarot orders and closes the numbered Major Arcana in this deck. Its earlier forms were not all identical, so today’s dancing figure should not be taken as a photograph of tarot’s first World card. What the subject offers is a way to picture a whole: the ordered world, a culminating state, or an encompassing view. Later interpreters developed that broad idea into accounts of spiritual completion and integration.',
      'Smith places a lightly draped figure within an oval wreath, with four beings in the corners. Waite interprets the card as perfection, completion, and the universe understood at a further stage. His discussion also connects it with the restored world rather than treating it as a simple trophy. The figure’s posture keeps the center active. The completed whole is not drawn as a sealed box in which nothing can happen, but as a balanced arrangement containing movement.',
      [['The oval wreath', 'The wreath encloses the figure without covering it. Its organic form makes the boundary feel living rather than architectural. A modern viewer can consider how an ending gives shape to experience while still leaving room for continued growth.'], ['The moving figure', 'The central body is posed rather than rigidly enthroned. That movement complicates a static idea of perfection. Completion can mean that different parts now work together, not that every future action or question has disappeared.'], ['The four corner beings', 'The human, eagle, lion, and bull echo figures seen on the Wheel of Fortune. The repetition links changing cycles with an image of wholeness. It invites comparison between the two cards rather than requiring that their scenes mean exactly the same thing.']],
      'Today the World often helps people acknowledge completion, integration, and the satisfaction of reaching a meaningful stage. Its history gives celebration a larger frame: finishing something changes how its parts can be understood together. A useful reading asks what has truly been completed, what can now be recognized or shared, and what belongs to a new chapter. It need not claim that a person has become flawless or that life will stop presenting difficulties.',
      'The four corner figures echo the Wheel, but the center has changed from a turning mechanism to a living figure. The deck revisits a visual vocabulary while changing its emphasis.'),
    'zh-CN': story('最后一张编号王牌，把完成画成仍然鲜活的运动。',
      '世界在历史塔罗排序中地位很高，也结束了本牌组有编号的大阿尔卡那。较早形式并不完全相同，不能把今天的舞动人物当作最初世界牌的直接复制。题材提供了一种描画整体的方式：有秩序的世界、达到顶点的状态，或包容一切的视野。后来的解释者由此发展精神完成与整合的论述。',
      '史密斯让轻纱围绕的人物站在椭圆花环中，四角各有生物。韦特讨论完善、完成与进入新阶段的宇宙，也把它联系到更新的世界，而不只是奖杯。人物姿态使中心保持活动：完成的整体不是封闭到什么都不能发生的盒子，而是包含运动的平衡安排。',
      [['椭圆花环', '花环围住人物，却没有遮蔽她。植物形态使边界显得有生命，而非建筑墙体。可以思考结束怎样给经验以形状，同时保留成长空间。'], ['运动中的人物', '中心身体处于动作姿态，而非僵坐王座，使完善不再静止。完成可以表示不同部分开始协作，而不是所有未来行动和问题都已消失。'], ['四角生物', '人、鹰、狮与牛呼应命运之轮的形象，把循环变化与整体相连。重复邀请比较，并不要求两张牌的场景意义完全相同。']],
      '今天，世界常帮助承认完成、整合，以及抵达重要阶段的满足。历史给予庆祝更大的框架：一件事完成后，其组成部分可以被重新一起理解。可以问真正完成了什么、现在能认出或分享什么，以及什么属于下一章。它不需要宣称人已经完美，或生活从此再无困难。',
      '四角生物呼应命运之轮，中心却从旋转机制变成鲜活人物。牌组重新使用视觉词汇，同时改变了重点。', true),
  },
  'major-09': {
    en: story('An old man’s light changes the meaning of being alone.',
      'The older tarot figure behind the Hermit can appear as an aged man associated with time. The Morgan’s Visconti-Sforza collection calls its example Time. Age, a staff, and an object held for inspection could evoke the passage of life before they became an invitation to retreat from daily noise. The modern word “hermit” therefore emphasizes one aspect of a changing image. It should not make us assume that every early version illustrated the same philosophy of solitude.',
      'Smith gives the solitary figure a lantern with a star inside and places him on a height. Waite stresses that the light is displayed rather than hidden beneath the cloak. He regards the figure as someone who has attained something and now holds out a beacon to others. This differs from the familiar picture of a seeker who knows nothing yet. The visual transformation turns withdrawal into a possible form of guidance: distance from the crowd need not mean rejection of other people.',
      [['The raised lantern', 'The light is held where someone else might see it. Its position makes the gesture outward-facing even though the figure stands alone. A reading focused only on isolation misses this small but important act of communication.'], ['The staff', 'The long staff gives physical support to the aged figure. It keeps the scene grounded in bodily need, even when the lantern invites spiritual associations. Experience does not make a person independent of practical support.'], ['The high ground', 'The elevated setting separates the Hermit from ordinary activity and broadens the space around him. A viewer might associate it with perspective or difficulty of access. The image leaves open how the figure arrived there and who may follow.']],
      'Today the Hermit is often used to discuss reflection, study, and time alone. Its history suggests adding a second question to “What do I need to discover?”: “What have I learned that could help someone else?” Solitude can be a setting for attention, but the lantern keeps relationship within the picture. The card is most interesting when retreat and return remain connected, rather than treating permanent withdrawal as the only sign of wisdom.',
      'Waite explicitly resists an interpretation of the Hermit as mere occult isolation. For him, the visible beacon is essential to the image.'),
    'zh-CN': story('老人手中的光，改变了独处的含义。',
      '隐者背后的较早塔罗人物，可以是一位与时间相关的老人。摩根图书馆把其维斯康蒂—斯福尔扎藏牌称为“时间”。年老、手杖与手中物件，可能先让人想到生命流逝，后来才成为离开喧闹生活的邀请。因此，“隐者”这个现代名称强调了变化图像中的某个层面，不能据此认定所有早期版本都说明同一套独处哲学。',
      '史密斯让独立高处的人举起一盏内有星形光芒的灯。韦特强调，灯光没有被披风遮住，而是向外展示；他认为人物已经有所成就，正把灯举给别人看。这与一无所知、仍在寻找答案的求道者不同。退隐因此也能成为引导：与人群保持距离，不必等于拒绝他人。',
      [['举起的灯', '灯放在别人可能看见的位置。即使人物独自站立，动作仍然朝向外界。只看到孤立，就会漏掉这个细小却重要的沟通。'], ['手杖', '长杖为年老人物提供身体支持，使精神象征仍然联系到现实需要。拥有经验并不表示不再需要实际支撑。'], ['高处', '高地把隐者与日常活动隔开，也扩大了周围空间。它可以使人想到视野或抵达的难度，画面却没有交代他如何到来，以及谁会跟随。']],
      '今天，隐者常谈反思、学习与独处。历史让“我需要发现什么”之外，还出现一个问题：“我已经学到什么，可以帮助别人？”独处能够支持专注，但灯光使关系始终留在画面里。退后与返回彼此相连，会比把永久远离视作唯一智慧更加丰富。',
      '韦特明确反对把隐者仅仅解释成神秘学意义上的隔绝。对他来说，灯光必须能被看见。', true),
  },
  'major-10': {
    en: story('A medieval image of changing fortune becomes a crowded diagram of movement and balance.',
      'The wheel of Fortune was a recognizable image long before modern tarot reading. A revolving wheel could show people rising to power and falling from it, making instability visible in one compact scene. Tarot inherited that broad subject. Its force did not depend on a theory that cards originated in ancient Egypt: anyone who had watched success change hands could understand the basic drama. Later occult authors added further systems to this established image of reversal.',
      'Smith’s wheel carries letters and signs, while creatures gather around its rim and in the corners. Waite says he followed reconstructions by Éliphas Lévi. He also makes a valuable distinction: using Egyptian symbols does not require claiming Egyptian origins for tarot. His explanation connects motion with a stable balancing principle, rather than treating the card as a simple promise of good luck. The design layers several traditions together and makes their combination visible.',
      [['The central wheel', 'The wheel appears suspended, turning without an ordinary axle or cart. Letters on its circumference make the object something to read as well as see. Its circular form encourages thought about recurrence, while a particular outcome remains unpictured.'], ['The sphinx above', 'A sphinx sits at the top rather than climbing or falling along the side. Waite interprets it as equilibrium amid movement. The arrangement creates a contrast between what changes and what appears to hold its position.'], ['The four corner figures', 'Winged figures occupy the corners and hold books. Waite connects them with the living creatures of Ezekiel. Their quiet reading surrounds the more active center, giving the whole scene a frame of order and contemplation.']],
      'The card is now often used to discuss turning points, cycles, and circumstances outside personal control. Remembering its older Fortune imagery can keep that reading balanced: rising does not prove permanent superiority, and falling does not define a person’s worth. A useful response is to distinguish changing conditions from the actions still available. Adaptability becomes more meaningful than trying to extract a guaranteed lucky outcome from the wheel.',
      'Waite himself warns that Egyptian symbolism does not establish Egyptian origins. The card supplies its own example of the difference between borrowing an image and proving a history.'),
    'zh-CN': story('中世纪的命运之轮，成为关于变化与平衡的繁复图像。',
      '在现代塔罗阅读出现之前，命运之轮已经是人们能认出的图像。旋转的轮子让人升至高位，也让人跌落，一幅小画便能展示不稳定。塔罗继承了这个广泛题材，它的力量无须依靠“牌来自古埃及”的说法：见过成功易手的人都能理解基本戏剧。后来的神秘主义作者又把更多体系加在这个旧图像上。',
      '史密斯的轮上有字母与符号，周围和四角聚集不同生物。韦特说明自己采用了利维的重构，也作出一个重要区分：使用埃及象征，并不需要主张塔罗起源于埃及。他把运动与稳定的平衡原则联系起来，而不是单纯许诺好运。多种传统在设计里层层相叠。',
      [['中央轮盘', '轮盘悬在空中，没有普通车轴或车辆。边缘字母使它既可观看也可阅读，圆形使人想到反复，但画面没有规定某个结果。'], ['顶端斯芬克斯', '斯芬克斯坐在顶端，没有像侧边生物那样上升或下降。韦特将它理解为运动中的平衡，使变化与保持位置形成对照。'], ['四角人物', '四个有翼形象手持书本。韦特把它们联系到《以西结书》的活物，安静阅读围住较活跃的中心，形成秩序与思考的框架。']],
      '今天，这张牌常谈转折、循环与不能由个人控制的环境。较早的命运形象让理解更平衡：上升不证明永久优越，下降也不决定一个人的价值。值得做的是区分变化的条件与仍能采取的行动。适应能力，比从轮子里索取必定走运的保证更有意义。',
      '韦特亲自提醒，埃及象征不能证明埃及起源。这张牌正好展示了借用图像与证明历史的不同。', true),
  },
  'major-11': {
    en: story('A familiar virtue keeps its scales while changing its place in the deck.',
      'Justice belongs to the moral and civic imagery that tarot inherited from its European setting. A figure with scales and a sword could make judgment and its consequences visible without any specialized knowledge of divination. Unlike some cards that were substantially redesigned, this subject retains strong continuity in its main attributes. That continuity concerns the image, however, and does not mean every legal, spiritual, or personal interpretation attached to it has always been the same.',
      'Smith places the crowned figure between pillars, holding an upright sword and balanced scales. Waite says the card largely follows traditional symbolism. Its conspicuous change is numerical: in this deck Justice is XI, while many other decks place it at VIII. The exchange with Strength is intentional. Waite also distinguishes the moral principle illustrated here from the spiritual mysteries he discusses under the High Priestess, even though both figures sit in similarly framed spaces.',
      [['The scales', 'Scales make comparison and proportion visible. They invite the question of what is being weighed and whether the available information is adequate. They do not show that a viewer’s preferred outcome is automatically the fair one.'], ['The upright sword', 'The vertical blade gives judgment a decisive edge. The picture joins consideration with the possibility of action, reminding a modern reader that fairness is more than a balanced opinion: decisions can have consequences for other people.'], ['The open eyes', 'The figure faces outward without a blindfold. That is a useful detail to notice before importing every feature of other Justice statues or paintings. This particular image presents judgment through a direct, visible encounter.']],
      'Today Justice often supports reflection on accountability, evidence, agreements, and the effects of choices. Its public history makes the card larger than a private feeling of being right. A thoughtful reading asks whose account has been heard, what standards are being applied, and whether the person making a decision accepts those same standards. The image can encourage careful responsibility without claiming to predict a court ruling or guarantee that events will be fair.',
      'The shared pillars do not make Justice a duplicate of the High Priestess. Waite explicitly uses the resemblance to explain a difference between their symbolic concerns.'),
    'zh-CN': story('熟悉的美德保留天平，却改变了自己在牌组中的位置。',
      '正义来自塔罗所处欧洲环境中的道德与公共图像。手持天平和剑的人物，不需要占卜知识也能让判断及其后果变得可见。与一些大幅重画的牌相比，它的主要标志有很强的延续性。但图像延续并不意味着附着在它上面的法律、精神或个人解释一直相同。',
      '史密斯让戴冠人物坐在柱子之间，持直立的剑与平衡的秤。韦特说它基本遵循传统象征，最醒目的变化则是编号：本牌组为十一号，许多其他牌组为八号，与力量的交换是有意安排。虽然正义与女祭司都坐在类似框架里，韦特仍区分前者的道德原则与后者的精神奥秘。',
      [['天平', '天平让比较与比例可见，邀请我们问正在衡量什么，以及资讯是否充分。它并没有说明观看者希望的结果就一定公平。'], ['直立的剑', '竖直剑刃让判断具有决断力，把考虑与行动相连。公平不只是平衡的意见，决定还会给别人带来后果。'], ['睁开的眼睛', '人物正面朝外，没有蒙眼。应先注意这一细节，再把其他正义雕像或画作的特征带入；本图以直接相见呈现判断。']],
      '今天，正义常帮助思考责任、证据、协议与选择的影响。公共历史使它大于私人“我有理”的感觉。值得问的是谁的叙述被听见、使用了什么标准，以及决策者是否接受相同标准。它鼓励认真负责，而不是预测诉讼结果或保证世界必然公平。',
      '相似的柱子没有使正义成为女祭司的复制品。韦特恰恰借这种相似来说明她们的象征关注不同。', true),
  },
  'major-12': {
    en: story('An unsettling upside-down body is transformed into an image of suspended life.',
      'The upside-down hanging figure is among tarot’s most arresting inherited subjects. Older descriptions can associate the card with a traitor, a reminder that an image now used for peaceful surrender once carried a harsher social atmosphere. Its exact early significance should not be reduced to a single confident story. What the visual history clearly preserves is an inverted human body, a situation that reverses ordinary posture and makes the viewer stop before it.',
      'Smith’s figure hangs by one foot from a leafy wooden structure, with a luminous circle around the head. Waite insists that the face shows absorption rather than suffering and that the wood is alive. He describes life held in suspension, not death. This interpretation turns the apparent punishment into a mystical state, without erasing the image’s discomfort. The change is a strong example of how later readers can redirect an inherited pose toward a different understanding.',
      [['The living wood', 'Leaves remain on the supporting structure. Waite specifically calls attention to them, because they distinguish a living tree of sacrifice from a merely dead apparatus. A small botanical detail changes the emotional setting of the whole scene.'], ['The luminous head', 'The bright circle contrasts with the unusual position of the body. It invites an association with insight or spiritual significance in Waite’s design. It is not evidence that every historical version presented the hanging person as enlightened.'], ['The bent leg', 'One leg crosses behind the other, giving the inverted body a deliberate, composed shape. The posture makes the figure appear more settled than struggling. A modern reading of changed perspective grows partly from this visual calm.']],
      'Today the Hanged Man often invites a pause, a changed viewpoint, or reconsideration of an effort that is going nowhere. Its history makes an important distinction possible: chosen suspension and imposed helplessness are not the same. A pause can be useful when it creates understanding, but suffering does not automatically become meaningful simply because it lasts. The card can help ask what a delay is revealing and what would allow movement again.',
      'Waite lists three concrete observations before interpreting the card: living wood, a calm face, and life in suspension. His explanation begins with looking closely.'),
    'zh-CN': story('令人不安的倒悬身体，被转化为生命暂时悬置的图像。',
      '倒悬人物是塔罗继承下来最引人注目的题材之一。较早描述可以把它联系到叛徒，提醒我们：今天常谈平静放下的图像，曾带有更严厉的社会意味。它最初的确切意义不宜压缩成一个过度肯定的故事。视觉历史明确保留的是倒转的人体，它颠覆普通姿态，使观看者停下来。',
      '史密斯的人物以单脚悬挂在带叶的木架上，头部有光圈。韦特坚持其面容表现沉思而非痛苦，并特别指出木头仍然有生命。他描述的是悬置的生命，不是死亡。这种解释把貌似惩罚的场景转为神秘状态，却没有抹掉不适感，清楚展示了后来阅读如何改变旧姿势的方向。',
      [['活木', '支架仍然长着叶子。韦特特别强调它，以区别有生命的牺牲之树与死物装置。细小植物特征改变了整幅画的情绪。'], ['头部光圈', '明亮圆圈与异常身体位置形成对比，在韦特设计中引向洞见或精神意义。但这不能证明所有历史版本都把悬挂者视作觉悟之人。'], ['弯曲的腿', '一腿弯到另一腿后方，使倒转身体形成有意识的构图。人物显得安定而非挣扎，现代“改变角度”的解释部分来自这种视觉平静。']],
      '今天，倒吊人常邀请暂停、换个角度，或重新考虑毫无进展的努力。历史帮助区分主动悬置与被迫无力。停顿若带来理解便可能有用，但痛苦不会只因持续很久就自动拥有意义。可以问等待揭示了什么，以及什么条件能让行动重新开始。',
      '韦特先列出三个具体观察：活木、平静面容，以及悬置中的生命。他的解释从仔细观看开始。', true),
  },
  'major-13': {
    en: story('A skeleton’s old reminder of mortality becomes a mounted procession through change.',
      'Death was already a powerful subject in European visual culture when tarot developed. Early cards could show a skeleton, making mortality recognizable without a private symbolic dictionary. The subject belongs to a world where images repeatedly reminded people that rank and possessions did not exempt anyone from dying. A modern interpretation centered on transformation can be valuable, but it should not erase the literal mortality that gave the older image much of its force.',
      'Smith presents an armored skeleton on a white horse, carrying a black banner. Waite explicitly prefers this apocalyptic horseman to the familiar reaping skeleton and interprets the design through transition and spiritual change. Different people meet the rider, while a sun appears between distant towers. The image combines an unavoidable interruption with a larger horizon. Its historical religious language and its modern psychological uses are connected, but they are not identical claims.',
      [['The rider without a weapon', 'The horseman carries a banner rather than a visible blade. Waite notes this absence. The scene’s power does not depend on showing a struggle that someone might win through force; the encounter has a different kind of inevitability.'], ['The different people', 'A fallen ruler, a religious figure, and younger people occupy the foreground. Their differences make the encounter collective rather than the private misfortune of one person. Status does not remove them from the scene.'], ['The distant sun', 'Light appears between two towers on the horizon. Waite gives it a spiritual interpretation involving immortality. A modern viewer can see continuity beyond an ending, while recognizing that this is symbolism rather than evidence about an afterlife.']],
      'Today Death often helps people discuss endings, letting go, and the transition between stages of life. The older image adds seriousness to that familiar reading: an ending can involve grief even when change is necessary. Reflection need not turn every loss into an immediate lesson. The card can support naming what has finished, honoring what mattered, and noticing what remains possible; it should not be used to predict someone’s death.',
      'Waite points out that the rider has no visible weapon. The banner, procession, and reactions carry the image’s meaning instead of a battle scene.'),
    'zh-CN': story('骷髅对死亡的古老提醒，成为穿越变化的骑行队列。',
      '塔罗出现时，死亡已经是欧洲视觉文化中的重要题材。早期牌可以画出骷髅，不需要私人象征字典就能让人想到生命有限。当时许多图像提醒人们，地位与财富不能让任何人免于死亡。现代“转变”的解释很有价值，却不应抹去旧图像原本直接面对死亡的力量。',
      '史密斯画出骑白马、披甲的骷髅，手持黑旗。韦特明确偏好这种启示录式骑士，而非熟悉的收割骷髅，并用过渡与精神变化解释它。不同人物面对骑士，远处两塔之间出现太阳。无法回避的中断与更远的地平线同时存在；历史宗教语言与现代心理运用相连，却并非同一种主张。',
      [['没有武器的骑士', '骑士拿着旗帜，没有可见刀刃，韦特也特别指出这一点。力量并不来自一场可以靠蛮力取胜的战斗，而是另一种不可回避。'], ['不同人物', '倒下的统治者、宗教人物与年轻人都在前景，使相遇不只是某一个人的私事。身份差异没有把他们排除在场景外。'], ['远处太阳', '光出现在地平线的双塔之间。韦特赋予它不朽的精神解释；现代观看者也可以看到终结之外的延续，但这仍是象征，不是来世证据。']],
      '今天，死神常帮助讨论结束、放下与人生阶段的过渡。旧图像为熟悉解释增添严肃性：即使改变必要，结束仍可能带来悲伤。反思不必立刻把所有损失变成一课。可以承认什么已经完成、尊重曾经重要的事，并发现仍然可能的方向，而不是用它预测某人的死亡。',
      '韦特指出骑士没有可见武器。旗帜、行进与人们的反应承担了意义，而不是战斗本身。', true),
  },
  'major-14': {
    en: story('The simple act of pouring becomes an art of bringing different things into relationship.',
      'Temperance is another of tarot’s inherited virtues. A person transferring liquid between vessels offered a recognizable way to picture moderation and mixture. The subject had a life in moral imagery before modern tarot handbooks made it a personal message about balance. Its ordinary action is part of its strength: unlike an abstract definition, pouring can show proportion, attention, and the possibility of spilling. A small domestic gesture becomes large enough to carry ethical meaning.',
      'Smith transforms the figure into a winged being with one foot on land and the other in water. Waite says the figure is neither male nor female and describes the liquid as the essences of life. He interprets tempering as a harmonizing of psychic and material natures. That is a specific mystical rereading of an older virtue. The picture retains the act of mixing while changing the scale of what is understood to be mixed.',
      [['The two cups', 'The liquid moves between separate vessels rather than disappearing into one undifferentiated container. The gesture makes relationship visible. A modern viewer can ask how different needs might be coordinated without assuming that all differences must be erased.'], ['Land and water', 'The figure stands across two kinds of ground. Waite explicitly connects this placement to the essences being combined. The stance also gives the picture a quiet physical difficulty: balance requires attention even when the surface looks peaceful.'], ['The distant path', 'A path leads away toward a bright horizon. It gives the calm foreground a direction and suggests that adjustment is part of a journey. Nothing in the picture requires the process to be instantaneous or complete.']],
      'Modern readings often connect Temperance with moderation, patience, and finding a sustainable rhythm. Its history helps distinguish balance from merely doing everything in equal amounts. Mixing depends on the qualities of the ingredients and the purpose of the mixture. The useful question is what proportion or sequence allows different parts of life to support each other, rather than whether every demand receives exactly the same share.',
      'Waite says the winged figure is neither male nor female. The image’s work of combination extends beyond the liquid in its cups.'),
    'zh-CN': story('一个简单的倒水动作，成为让不同事物建立关系的艺术。',
      '节制也是塔罗继承下来的美德题材。人物把液体从一个容器倒入另一个，容易让人理解适量与调和。在现代手册把它用作个人平衡提醒以前，这个主题已经存在于道德图像中。普通动作正是它的力量：倒水能表现比例、专注与溢出的可能，小小生活动作由此承载伦理意义。',
      '史密斯把人物变成有翼形象，一脚踏地，一脚入水。韦特说它既非男性也非女性，把液体解释为生命的精华，并把调和理解为精神与物质本性的协调。这是对旧美德的特定神秘主义重读：混合动作仍然保留，被混合之物的规模却改变了。',
      [['两只杯子', '液体在分开的容器之间流动，没有直接消失在一个无差别容器里。动作让关系可见，可以使人思考如何协调不同需要，而不是消灭所有差别。'], ['土地与水', '人物跨在两种环境之间。韦特明确把脚的位置与混合的精华联系起来，姿势也提示平衡需要关注，即使表面看起来安静。'], ['远处小路', '小路通向明亮地平线，为平静前景赋予方向，说明调整也是旅程的一部分。画面没有要求过程必须瞬间完成。']],
      '今天，节制常谈适度、耐心与可持续节奏。历史帮助区别平衡与“每件事都分到一样多”。调配要看材料性质与目的。值得问的是，什么比例或顺序让生活的不同部分相互支持，而不是所有要求是否得到完全相同的份额。',
      '韦特说有翼人物既非男性也非女性。图像的调和工作，超出了杯中液体本身。', true),
  },
  'major-15': {
    en: story('A frightening religious figure becomes a picture of bondage that also contains the possibility of release.',
      'The Devil belongs to tarot’s inherited religious imagery. Horns, wings, distorted anatomy, and subordinate human figures could make spiritual danger recognizable in a Christian visual world. The existence of this image in tarot does not make the cards evidence of devil worship; representing a feared being is not the same as honoring it. Later occult writers reworked the subject with additional symbols, and their disagreement about its meaning is part of the card’s history.',
      'Smith shows a horned, winged figure above two chained people. Waite describes the design as a combination of several motives and discusses Lévi’s interpretation critically. He connects the human figures with bondage in material life, but also says their master will not rule them forever. That qualification is important. The scene is oppressive, yet his account does not reduce the people to a permanently fixed condition without intelligence or possibility.',
      [['The chains', 'The chains visibly connect the people to the central structure. A modern reader may see dependency, coercion, or habits that have become difficult to interrupt. The image alone cannot determine whether a real person can leave a harmful situation without support.'], ['The two people', 'They remain recognizably human despite their animal-like additions. Their similarity to figures elsewhere in the deck invites comparison between relationship and bondage. It is more useful to examine the arrangement than to treat the people as inherently bad.'], ['The downward torch', 'The torch points toward the earth rather than lifting light upward. Together with the raised hand, it changes familiar gestures into an unsettling arrangement. Waite compares the hand with a reversed form of the Hierophant’s blessing.']],
      'Today the Devil is often used to discuss compulsions, limiting agreements, and the difference between desire and loss of choice. Its history makes it possible to take these themes seriously without treating the card as a supernatural diagnosis. A useful reading asks what strengthens a binding pattern and what concrete help could loosen it. Recognizing a difficulty is a beginning, not proof that overcoming it must be easy.',
      'Waite’s explanation includes the idea that the dominating figure will not remain master forever. Possibility is present even within his account of bondage.'),
    'zh-CN': story('可怕的宗教人物成为束缚的图像，而图像里也保留了松脱的可能。',
      '恶魔属于塔罗继承下来的宗教图像。角、翅膀、变形身体与受制的人物，在基督教视觉环境中容易让人理解精神危险。牌上出现恶魔，并不证明塔罗是恶魔崇拜：描绘令人害怕的存在，与尊奉它不是一回事。后来的神秘主义作者加入新符号，彼此对意义的争论，也属于历史。',
      '史密斯让有角、有翼的形象凌驾于两个被链住的人之上。韦特称设计结合了多种主题，并批评性地讨论利维的解释。他把人物联系到物质生活的束缚，却也说他们的主人不会永远统治。这一点重要：画面压迫，但解释没有把人变成永久失去智慧与可能性的存在。',
      [['锁链', '锁链把人物与中心结构联系起来，今天可以让人想到依赖、胁迫或难以打断的习惯。但仅凭图像，不能判断现实中的人是否能在没有支持时离开伤害环境。'], ['两个人', '即使有动物般的附加特征，他们仍明显是人。与牌组其他人物的相似，使人比较关系与束缚，而不是把人物本身判断为邪恶。'], ['向下火炬', '火炬指向地面，没有向上举光。它与举起的手让熟悉动作变得不安；韦特把手势与教皇祝福的反转形式相比较。']],
      '今天，恶魔常用于讨论强迫模式、限制性约定，以及欲望与失去选择的区别。历史让这些主题能被认真对待，而不必作超自然诊断。可以问什么使束缚变强，以及哪些具体帮助能让它松动。认识困难是起点，并不证明解决它必定轻松。',
      '韦特的解释包含“统治者不会永远是主人”的想法。即使在束缚叙述中，可能性也没有完全消失。', true),
  },
  'major-00': {
    en: story('Before becoming a symbol of fresh starts, the Fool stood outside the ordinary order of the cards.',
      'The Fool has always been an unusual member of the tarot family. Early Italian packs included a figure called the matto alongside their numbered or ranked trumps. Its exceptional role in play helps explain why it does not fit comfortably into a simple ladder of power. Earlier images could present a ragged outsider, making folly and social exclusion visible. That history is quite different from the cheerful advice to “take a leap” that many readers now associate with the card.',
      'Smith’s traveler wears bright patterned clothing and holds a white flower. The precipice remains dangerous, yet the scene is full of sunshine. Waite described a spirit seeking experience and deliberately distinguished this figure from earlier ideas of mere foolishness. That change transforms an outsider into a protagonist. Numbering the card zero makes it easy to imagine a beginning, but the familiar practice of treating the entire Major Arcana as the Fool’s personal adventure should not be mistaken for a documented Renaissance storyline.',
      [['The cliff', 'The traveler stands at an edge, not already in midair. That suspended moment lets a modern reader hold curiosity and caution together. The image offers possibility without showing whether the next step will succeed.'], ['The little dog', 'A small dog leaps beside the traveler. It can suggest companionship, excitement, instinct, or warning to a viewer. Those possibilities are readings of the picture, rather than evidence of one universally fixed code.'], ['The bundle and rose', 'The bundle implies that the traveler carries something from elsewhere, while the flower makes the encounter with the world seem gentle. Their contrast gives the journey both a past and an immediate openness.']],
      'Today the Fool often introduces beginnings, experimentation, and the willingness to learn. Its older history adds a useful complication: being outside the established order can mean freedom, but also vulnerability. The most interesting question is not simply whether to jump. It is what kind of beginner you want to be, what you already carry, and what deserves your attention before you move.',
      'Waite discusses the zero card after Judgement in his book. Even the printed order reminds us that the Fool has resisted a single tidy position.'),
    'zh-CN': story('成为新开始的象征以前，愚者就已经站在牌的通常秩序之外。',
      '愚者一直是塔罗家族中的特殊成员。早期意大利牌组把称为matto的愚者与王牌放在一起，它在游戏中的特殊作用，也解释了为什么它不容易被放进一条从低到高的权力阶梯。较早的形象可以是衣衫褴褛的边缘人物，让愚行与社会排斥变得可见。这与今天常见的“勇敢迈出一步”并不是同一层意思。',
      '史密斯的旅人穿着明亮的花纹衣服，手持白花。悬崖仍然危险，整幅画却充满阳光。韦特把他解释为寻求经验的精神，刻意区别于单纯愚蠢的旧形象：边缘人变成了故事主角。零这个编号很容易使人想到起点，但把整套大阿尔卡那当作愚者人生旅程的做法，不应被说成已有文献证实的文艺复兴叙事。',
      [['悬崖', '旅人停在边缘，还没有腾空跃下。这个悬而未决的瞬间让好奇与谨慎同时存在，画面展现的是可能性，没有替下一步保证成功。'], ['小狗', '狗在旅人身边跳跃，可以让人想到陪伴、兴奋、直觉或提醒。这些都是观看图像时产生的理解，而不是唯一固定的密码。'], ['包袱与白花', '包袱暗示旅人从别处带来了某些东西，花则让他面对世界的态度显得温柔。他既拥有过去，也保持着当下的开放。']],
      '今天，愚者常用来谈开始、尝试与学习意愿。更早的历史补充了另一面：置身既定秩序之外，既可能意味着自由，也可能意味着脆弱。有意思的问题不只是要不要跳，而是你希望做怎样的初学者、已经带着什么，以及出发前值得留意什么。',
      '韦特在书中把零号愚者放在审判之后讨论。连书页顺序都提醒我们：它从来不容易被固定在一个位置。', true),
  },
  'major-01': {
    en: story('A street performer’s table becomes a stage for focused will and spiritual aspiration.',
      'An early ancestor of the Magician is the bagatto, often understood as a performer or juggler. A person standing behind a table of small objects could evoke dexterity, entertainment, and the uncertain border between skill and trickery. The Morgan’s surviving Visconti-Sforza collection labels its example The Juggler. This is a useful starting point: the card did not arrive fully formed as a modern promise that thought alone can produce whatever someone desires.',
      'In the Rider–Waite–Smith image, the table becomes a carefully arranged symbolic workspace. A wand, cup, sword, and pentacle connect the figure with the deck’s four suits. Waite described the raised and lowered hands as a communication between spiritual and earthly levels. Smith makes that abstract relationship immediately legible through a single bodily gesture. The resulting figure looks less like someone amusing an audience and more like someone concentrating available powers into a purposeful act.',
      [['The two hands', 'One hand raises a wand while the other points downward. The gesture links different levels of the composition. For Waite it carried a spiritual meaning; a practical modern reading can see the movement from intention toward action.'], ['The four tools', 'All four suit emblems lie within reach. They invite comparison with the many kinds of resources a task requires. They do not demonstrate that the figure can ignore material limits or accomplish something through wishing alone.'], ['The garden', 'Roses and lilies surround the scene. Waite explicitly connected the cultivated flowers with aspiration. The garden adds an idea of tending and growth to an image that might otherwise seem to concern instant power.']],
      'The card’s history makes it especially interesting when questions of ability and presentation overlap. Are you practicing a skill, making a persuasive promise, or confusing the two? A modern reading of initiative becomes richer when it remembers the performer behind the mystic. Confidence can help begin a project, but its value becomes clear through the work that follows and the honesty of the claims made about it.',
      'The infinity-like sign over the head is not the only image of continuity here: Waite also describes the belt as a serpent biting its own tail.'),
    'zh-CN': story('街头表演者的桌子，变成了集中意志与精神追求的舞台。',
      '魔术师较早的前身是bagatto，通常被理解为表演者或杂耍艺人。一个站在小物件后面的人，能让观众想到灵巧、娱乐，以及技巧与欺骗之间不确定的边界。摩根图书馆的维斯康蒂—斯福尔扎藏牌便把这一形象称为杂耍者。因此，它并不是从一开始就在承诺“只凭想法便能实现愿望”。',
      '在韦特—史密斯图像中，桌子成为精心安排的象征工作台。权杖、圣杯、宝剑与星币把人物连接到四个花色。韦特将一高一低的双手解释为精神与尘世层面的沟通，史密斯则用一个身体姿势让抽象关系清晰可见。人物不再只是逗乐观众，而像在把能够运用的力量集中到一件事上。',
      [['双手', '一手举起杖，另一手指向地面，连接了画面中的不同层次。韦特赋予它精神意义；今天也可以把它看作让意图走向行动的过程。'], ['四件工具', '四种花色的标志都在伸手可及之处，让人想到一项工作需要不同资源。它们并不表示可以忽略现实限制，或仅靠愿望完成任务。'], ['花园', '玫瑰与百合围绕人物。韦特把栽培的花朵与志向相联系，使看似瞬间发生的力量，也包含照料与成长的过程。']],
      '当能力与表现互相交织时，这张牌尤其有趣：你是在练习技巧、作出动人的承诺，还是把二者混为一谈？在神秘主义者身后看见表演者，会让“主动行动”的现代解释更加丰富。信心能帮助开始，但它的价值最终仍要通过后续工作，以及对自身能力的诚实表达来体现。',
      '头顶像无限符号的图案并非唯一的循环象征：韦特还把腰带描述为一条咬住自己尾巴的蛇。', true),
  },
  'major-02': {
    en: story('The old Popess becomes a guardian of a threshold, where seeing is different from understanding.',
      'The High Priestess descends from the Popess, a female pontiff present in early Italian tarot. That unusual figure has encouraged many proposed identifications. A specific historical woman or a particular legend should not be treated as a settled explanation without evidence. What is secure is the older card’s religious appearance and its place among figures of spiritual and worldly authority. Its later transformation shows how an inherited image can acquire a different name and a new symbolic setting.',
      'Smith places the seated figure between black and white pillars, in front of a patterned veil. Waite’s commentary combines biblical, Christian mystical, and Kabbalistic references. He calls attention to the partially covered scroll and describes knowledge that is both spoken and implied. These are his early twentieth-century interpretations, not proof that medieval cardmakers concealed the same system. The new title shifts attention from an unusual holder of a church office to a person who seems to guard access to understanding.',
      [['The covered scroll', 'The scroll bears the letters TORA and disappears partly beneath the mantle. Waite interprets this partial concealment as a distinction between what can be stated and what remains implicit. The visual device asks the viewer to notice incomplete access.'], ['The paired pillars', 'Light and dark pillars frame the figure without swallowing her into either side. Their letters and temple associations belong to the deck’s symbolic construction. They create a threshold, rather than a simple illustration of good battling evil.'], ['The veil', 'Palms and pomegranates decorate the screen behind her. The scene invites curiosity about what lies beyond while keeping it hidden. That tension is one reason the picture lends itself so naturally to readings about patient attention.']],
      'Modern readers often connect the card with intuition, quiet observation, and information not yet available. Its history encourages a careful version of that idea: mystery does not authorize certainty. A feeling may be worth listening to while still needing context and evidence. The card can therefore prompt a productive pause, a question about what remains unseen, or a distinction between privacy and secrecy.',
      'Waite contrasts the Priestess with the Hierophant: she makes no blessing gesture. In his scheme, silence and public instruction express different kinds of religious authority.'),
    'zh-CN': story('古老的女教宗成为门槛的守护者，提醒我们：看见与理解并不相同。',
      '女祭司承接了早期意大利塔罗中的女教宗形象。这个特殊人物引发过许多身份猜想，但在证据不足时，不应把某位历史女性或某个传说说成定论。较为确定的是，她具有宗教外观，并与精神及世俗权威人物并列。后来的变化，展示了旧图像如何获得新名称与新象征环境。',
      '史密斯让她坐在黑白柱之间，背后是一面带花纹的帷幕。韦特的说明结合了《圣经》、基督教神秘主义与卡巴拉意象。他特别注意到被遮住一部分的卷轴，谈到明说与暗示的知识。这是二十世纪初作者的解释，并不能证明中世纪制牌者已经隐藏了相同体系。新名称也把注意力从特殊的教会职位，转向对理解之门的守护。',
      [['半遮的卷轴', '卷轴上可见TORA字样，一部分藏在披风下。韦特把这种安排理解为明说与暗示的区别，画面则让人直接感到知识尚未完全展开。'], ['两根柱子', '黑白柱围住人物，却没有把她吞没在任何一边。柱上的字母与圣殿联系属于这套牌的象征设计，形成一道门槛，而不是简单的善恶争斗。'], ['帷幕', '棕榈与石榴装饰着背后的屏障，使人好奇另一边的事物，却又无法立刻看清。这种张力也让牌自然适合谈耐心观察。']],
      '现代读者常把她联系到直觉、安静观察与尚未掌握的资讯。历史让这种理解更谨慎：神秘感并不能带来确定性。感受值得倾听，同时仍需要背景与证据。因此，这张牌可以提醒人暂停，询问遗漏了什么，并分清隐私与刻意隐瞒。',
      '韦特特别把女祭司与教皇相比：她没有作出祝福手势。在他的体系中，沉默与公开教导体现了不同的宗教权威。', true),
  },
  'major-03': {
    en: story('A ruler leaves the palace and becomes the center of a living landscape.',
      'The Empress belonged to tarot’s early company of worldly and religious authorities. An imperial woman with regalia would have been intelligible to players without a divination handbook: she represented rank and the public imagery of rule. The surviving early decks establish the antiquity of the subject, but not every modern association attached to it. Motherhood, artistic creativity, pleasure, and abundance are layers of interpretation, rather than a single original definition that has remained unchanged.',
      'Smith places the Empress amid trees, flowing water, and ripening grain. The move into a fertile landscape matters as much as her crown. Waite describes the visible world and the entrance into embodied life, giving the scene a spiritual significance through its material richness. His language reflects the gender assumptions of his period. A reader can understand that historical framework without making womanhood, fertility, or caregiving compulsory descriptions of any particular person.',
      [['The starry crown', 'Twelve stars gather around the crown. The ruler’s authority is now framed by a larger cosmic setting. Their presence invites attention to the whole composition rather than a claim that one numerical interpretation exhausts the image.'], ['The Venus emblem', 'A shield bears the familiar sign associated with Venus. In this setting it helps connect sovereignty with beauty and generative life. It is a deliberate feature of this deck, not evidence that the early Empress was an ancient Venus card.'], ['The grain and water', 'Ripening plants and moving water surround the seated figure. They make abundance look like a living process that depends on conditions. The picture can therefore suggest nourishment and continuity as well as possession.']],
      'Today the Empress often offers a language for care, creativity, and giving something room to grow. Her movement from imperial rank into a landscape makes a useful question possible: what does your influence help to flourish? The image can concern a garden, a project, a community, or care for oneself. It need not predict pregnancy or assign a fixed family role to the person who encounters it.',
      'The Empress carries a sceptre, but most of the scene’s activity comes from growing plants and running water. Authority is pictured inside an ecosystem.'),
    'zh-CN': story('一位统治者走出宫殿，成为生机盎然的风景中心。',
      '皇后属于早期塔罗中的世俗与宗教权威人物。手持权杖、佩戴王冠的帝国女性，不需要占卜手册也能让玩家理解：她代表身份与统治的公共形象。早期存世牌证明了这个题材的悠久，却不能证明每一种现代解释同样古老。母性、创造力、享受与丰盛，是后来形成的不同解读层次。',
      '史密斯让皇后置身树木、流水与成熟谷物之间，从宫廷进入丰饶大地的变化，与王冠同样重要。韦特把她联系到可见世界与进入生命的门户，通过物质的丰富赋予画面精神意义。他的措辞也带着时代的性别观念。了解这些背景，并不意味着必须把女性身份、生育或照顾他人当成某个人的规定角色。',
      [['星冠', '十二颗星环绕王冠，让统治者进入更大的宇宙背景。它们鼓励观看整幅画，而不是认定一种数字解释就穷尽了图像。'], ['金星符号', '盾牌上是与金星相联系的标志，使权力与美、生命的生成产生联系。这是本牌组的具体设计，不是早期皇后源自古代金星牌的证据。'], ['谷物与流水', '成熟的植物与流动的水让丰盛呈现为依赖环境的生命过程，因此画面不仅谈拥有，也谈滋养与持续。']],
      '今天，皇后常用于谈照料、创造与给成长留出空间。从帝国身份走入自然风景，也带来一个问题：你的影响力让什么得以繁荣？它可以关乎花园、项目、社群或自我照顾，无须被当作怀孕预告，也无须替任何人规定家庭角色。',
      '皇后虽然持有权杖，画面中大部分活动却来自植物生长与水流。权威被安放在一个生态系统里。', true),
  },
  'major-04': {
    en: story('The throne promises stability, but its stone also asks what stability costs.',
      'The Emperor is one of tarot’s most recognizable inherited figures. Early players lived in a world where imperial and papal authority were important political images, so a crowned ruler did not need to be explained as a personality type. The card’s presence beside the Empress and religious figures places it within that larger visual hierarchy. Reading it solely as a stern father loses this public dimension and treats a modern psychological interpretation as if it were the whole history.',
      'Smith’s Emperor sits facing the viewer on a substantial throne, with mountains behind him. Waite interprets the figure as executive power and the rule of thought. The picture supports that emphasis through its squared forms and frontal posture. Unlike the richly vegetated Empress, this ruler occupies a comparatively austere landscape. The contrast allows the pair to explore different ways authority is imagined, without requiring them to portray a literal married couple or a universal division of gender roles.',
      [['The stone throne', 'Its strong geometry gives the seated figure weight and permanence. A modern viewer can read dependable structure here, but also inflexibility. The same visual feature supports both possibilities because firmness is not automatically wisdom.'], ['The ram heads', 'Rams decorate the throne and give its outline a forceful character. Their presence is visible evidence; a detailed astrological system is a further interpretive framework and should be named as such rather than assumed.'], ['The sceptre and globe', 'These objects make authority something displayed and held. Waite notes the sceptre’s ankh-like form. The combination links governing power to symbolic claims about life and dominion, rather than merely to physical strength.']],
      'Contemporary readings often use the Emperor to discuss responsibility, rules, and the ability to make a plan hold together. The history of the image adds a social question: who benefits from those rules, and who gets to make them? Good structure can protect people and make cooperation possible. A thoughtful reading examines whether authority serves a purpose, instead of simply celebrating control for its own sake.',
      'Waite explicitly says that the Emperor and Empress are not simply pictures of married life. Their relationship operates on more than one symbolic level.'),
    'zh-CN': story('石座承诺稳定，也让人思考稳定需要付出什么。',
      '皇帝是塔罗继承下来的最容易辨认的人物之一。早期玩家所处的世界重视帝国与教宗权威，因此戴冠统治者并不需要先被解释为一种性格。他与皇后及宗教人物并列，属于更大的视觉等级体系。如果只把他当成严厉父亲，就会忽略公共政治层面，把现代心理解释误当作全部历史。',
      '史密斯笔下的皇帝正面坐在厚重王座上，背后耸立山峰。韦特用执行力与思想的统治解释他，方正构图和正面姿态也加强了这种感觉。相比皇后茂盛的环境，他的风景显得严峻。这种对照可以探讨不同权威方式，不必把两人限定为真实夫妻，也不必把差异变成普遍的性别规则。',
      [['石座', '强烈的几何形状赋予人物重量与持久感。它可以让人想到可靠结构，也可能意味着僵硬；坚定本身并不自动等于智慧。'], ['公羊头', '王座上的公羊装饰使轮廓更有力量。装饰本身是可见事实，进一步的占星对应则属于需要明确说明的解释体系。'], ['权杖与球体', '统治通过手持和展示的物件变得可见。韦特注意到权杖类似生命之符的形状，让权力联系到生命与疆域，而不只是体力。']],
      '现代阅读常用皇帝讨论责任、规则与落实计划的能力。图像历史又补充了一个社会问题：规则使谁受益，又由谁制定？良好结构可以保护人、促成合作。值得思考的是权威是否服务于某种目的，而不只是赞美控制本身。',
      '韦特明确说过，皇帝与皇后不只是婚姻生活的描绘。他们的关系可以同时在多个象征层面展开。', true),
  },
  'major-05': {
    en: story('The Pope becomes a broader image of teaching, ceremony, and the institutions that preserve belief.',
      'This card’s older title is the Pope. In early tarot, that figure stood among the deck’s recognizable authorities, alongside secular rulers and the unusual Popess. The religious setting was part of the world in which the cards circulated. It is therefore misleading to treat every Christian detail as a disguise for a single lost non-Christian system. Later occult writers reread the inherited image, giving it purposes that differed from those of a Renaissance card game.',
      'The name Hierophant broadens the subject toward the revealing or teaching of sacred matters, but Smith keeps unmistakable papal imagery. Waite describes the public, institutional side of religion and contrasts it with the Priestess’s withdrawn authority. He is not simply praising obedience: his discussion recognizes that the officeholder may mistake personal limits for the full meaning of the office. The history of this card is therefore about mediation, not just someone at the top issuing orders.',
      [['The crossed keys', 'The keys beneath the figure refer to religious authority and access. Their position places that authority between teacher and attendants. They make an abstract claim about permission or transmission into something the viewer can immediately recognize.'], ['The two attendants', 'The kneeling figures turn a solitary portrait into a scene of teaching and reception. They show that traditions persist through relationships and shared practice. Whether that relationship feels supportive or restrictive remains an interpretive question.'], ['The raised hand', 'The blessing gesture gives the card a public, communicative quality. Waite explicitly notices its difference from the silent High Priestess. The contrast helps explain why these two superficially similar seated figures are not interchangeable.']],
      'Today readers often connect the Hierophant with education, inherited values, ceremonies, or finding a mentor. A useful question is how a tradition becomes meaningful through practice rather than simple repetition. Institutions can preserve knowledge that no individual could invent alone, yet they can also become rigid. The card’s historical religious setting gives that tension substance without requiring every reading to concern organized religion.',
      'Despite the new title, the triple crown and crossed keys remain. The illustration lets an older identity show through a later interpretation.'),
    'zh-CN': story('教宗成为更广义的图像，谈教导、仪式，以及保存信念的制度。',
      '这张牌较早的名称就是教宗。早期塔罗把他与世俗统治者、特殊的女教宗并列，属于容易辨认的权威人物。宗教环境本来就是牌流通的世界，因此不能把所有基督教细节都说成某种失落体系的伪装。后来的神秘主义作者重新解释旧图像，让它承担了不同于文艺复兴纸牌游戏的任务。',
      'Hierophant这个名称把题材拓宽到神圣事务的展示与传授，史密斯却保留了明显的教宗形象。韦特讨论宗教公开、制度化的一面，并将它与女祭司内在的权威对比。他也不是单纯赞美服从：他提醒职位持有者可能把自己的有限理解，误当作整个职位的意义。因此，这张牌也关乎传承与中介。',
      [['交叉钥匙', '钥匙让宗教权威与进入资格变得可见，位置介于教师与侍者之间。抽象的许可与传授，被转化成观众能认出的物件。'], ['两位侍者', '跪着的人物让肖像变成教学与接受的场景，说明传统通过关系和共同实践延续。这样的关系令人支持还是受限，仍需要具体判断。'], ['举起的手', '祝福动作赋予画面公开传达的性质。韦特特别指出它与沉默的女祭司不同，帮助我们理解两位看似相似的坐姿人物为何不能互换。']],
      '现代读者常把教皇联系到教育、继承的价值、仪式或导师。一个有用的问题是：传统怎样通过实践获得意义，而不只是反复重复？制度能保存个人无法独自创造的知识，也可能变得僵化。原本的宗教背景让这种张力更具体，但并不要求每一次阅读都只谈宗教组织。',
      '名称虽然改变，三重冠与交叉钥匙仍然保留。新的解释之下，旧身份依旧清楚可见。', true),
  },
  'major-06': {
    en: story('A scene of human love is redesigned as a meeting in a garden before the Fall.',
      'Love is present among the subjects of early Italian tarot, and older versions can show a marriage or a person placed between other figures. These images did not all tell the same story. Waite himself distinguishes the marriage scene from later interpretations of a choice between vice and virtue. That variety matters: the familiar modern phrase “a choice aligned with your values” is a useful reading, but it is not a description of one unchanged picture handed down through the centuries.',
      'Smith’s Lovers are naked beneath a great winged figure, with trees behind them and a mountain between them. Waite explicitly connects them to Adam and Eve and says that this design replaces older arrangements. The garden gives the encounter a theological setting rather than simply illustrating a romantic couple. It also makes vulnerability visible: there are no clothes or social insignia between the two people. Waite’s gendered interpretation belongs to his period and need not govern a modern understanding of relationships.',
      [['The two trees', 'The trees are different, and a serpent winds around the one behind the woman. In Waite’s account they locate the scene in an Edenic story. They also make the image asymmetrical, even though the two human figures appear balanced.'], ['The winged figure', 'Its open arms stretch above both people. This larger presence places human connection within a spiritual framework. Naming it beyond what a source supports should be distinguished from simply observing the form of the picture.'], ['The open bodies', 'Neither person wears armour, a crown, or ceremonial clothing. A present-day viewer may see honesty and exposure here. That response grows from the visual scene, rather than requiring a belief that the card predicts a particular partner.']],
      'Today the Lovers can open a conversation about mutual choice, consent, shared values, and the difference between attraction and commitment. Its changing pictures show why no single keyword can contain it. The scene may concern intimacy, but it can also invite reflection on how a decision joins different parts of a life. The essential modern question is what kind of relationship an honest choice makes possible.',
      'Waite openly says he replaced earlier Lovers imagery. This is a documented redesign, not a perfectly preserved ancient scene.'),
    'zh-CN': story('人的爱情被重新画成伊甸园中的相遇。',
      '爱情已经出现在早期意大利塔罗的题材中，旧版本可以呈现婚姻，也可以让一个人站在其他人物之间。这些图像并非一直讲同一个故事。韦特本人便区分了婚姻场景与后来“在美德和恶行之间选择”的解释。因此，今天常说的“依照价值作选择”是有用的阅读方式，却不是一幅几百年从未改变的画的简单说明。',
      '史密斯的恋人赤身站在大型有翼人物之下，身后各有树木，中间远处有山。韦特明确联系到亚当与夏娃，并说这种设计替换了较早的安排。花园赋予相遇神学背景，也让脆弱变得可见：两人之间没有衣着或社会身份的标志。韦特带有时代色彩的性别解释，并不必支配今天对关系的理解。',
      [['两棵树', '树的形态不同，女人身后的树上缠着蛇。在韦特的说明中，它们把场景放进伊甸园故事；同时，也让看似平衡的构图包含差异。'], ['有翼人物', '展开的双臂覆盖两个人，把人际联系放进精神框架。若进一步给它确定身份，需要与单纯观察画面区别开来。'], ['敞开的身体', '两人没有铠甲、王冠或礼服。今天的观看者可能由此想到坦诚与暴露，这种理解来自画面，无须相信牌会预告特定伴侣。']],
      '今天，恋人可以帮助讨论共同选择、同意、价值观，以及吸引与承诺的区别。图像的历史变化解释了为什么一个关键词无法概括它。它既可以关乎亲密，也可以让人思考某个决定如何连接生活的不同部分：诚实的选择，会使怎样的关系成为可能？',
      '韦特公开说明自己替换了旧的恋人图像。这是有文献记录的重新设计，而不是完整不变的古老场景。', true),
  },
  'major-07': {
    en: story('A triumphal vehicle becomes a puzzle about direction, mastery, and the limits of victory.',
      'The Chariot belongs to the early tarot repertoire, where a ruler or victorious figure in a vehicle could draw on the familiar language of triumph. Such an image communicates elevated status and movement even without a hidden symbolic code. Different historical versions change the passenger and the vehicle’s details. The durable subject is a public display of mastery. Later occult interpretation takes that visible success and asks whether outer conquest also amounts to inward understanding.',
      'Smith replaces ordinary draft animals with a black and a white sphinx. Waite explicitly credits Éliphas Lévi for the sphinx variation, making this a particularly clear example of a nineteenth-century idea entering a twentieth-century deck. The armored figure stands under a starry canopy with a city behind him. The chariot looks imposing, but its forward movement is not actually shown. That pause makes the viewer consider how the parts of the scene might be brought into agreement.',
      [['The two sphinxes', 'The contrasting creatures face the viewer and appear to rest rather than run. Waite links them to a riddle of nature and intellectual conquest. Their Egyptian appearance is a chosen symbol, not proof that tarot originated in Egypt.'], ['The armour', 'The passenger is protected and ceremonially equipped. Armour can signify readiness, but it can also separate the person from the world outside. The image permits a question about what protection makes possible and what it prevents.'], ['The city behind', 'The buildings provide a place from which the chariot appears to have emerged. A modern viewer can read departure and independence here, while remembering that the image does not show a destination or guarantee a successful journey.']],
      'Readers today often connect the Chariot with determination and bringing competing impulses into one direction. Its history adds an important limit: success in an external contest is not the same as knowing oneself. A useful reading asks what victory would actually mean, which forces need coordination, and whether the chosen route serves the intended goal. Willpower becomes more interesting when it has a direction worth maintaining.',
      'The sphinxes have a named predecessor in Waite’s own account: Lévi. Here we can identify a specific act of borrowing rather than invent an ancient origin.'),
    'zh-CN': story('凯旋的车辆成为一道关于方向、掌控与胜利局限的谜题。',
      '战车属于早期塔罗题材，车中的统治者或胜利者借用了人们熟悉的凯旋形象。不需要隐藏密码，这种画面也能传达地位与前进。不同版本会改变乘客与车辆细节，持续存在的主题则是公开展示掌控力。后来的神秘主义解释进一步追问：外在征服是否也意味着内在理解？',
      '史密斯用一黑一白的斯芬克斯替换普通牵引动物。韦特明确将这种变化归于艾利法斯·利维，清楚展示了十九世纪思想如何进入二十世纪牌组。披甲人物站在星纹车篷下，身后是城市。战车看似威严，却没有真正被画成正在前进；这种停顿使人思考，各部分该怎样协调。',
      [['两只斯芬克斯', '两只对照的动物面向观众，看起来是在休息而非奔跑。韦特把它们联系到自然之谜与智性征服。埃及式外观是选择的象征，不是塔罗起源于埃及的证据。'], ['铠甲', '乘客受到保护，也穿戴着仪式性的装备。它可以意味准备充分，也可能把人与外界隔开，值得思考保护带来了什么，又限制了什么。'], ['身后的城市', '建筑给予战车一个仿佛刚刚离开的地方。今天可以由此理解出发与独立，但画面没有展现目的地，也没有保证旅程成功。']],
      '现代读者常把战车联系到决心，以及让相互竞争的冲动朝同一方向前进。历史补充了一个重要限制：赢得外在竞赛并不等于认识自己。可以问胜利具体意味着什么、哪些力量需要协调，以及选定的路线是否服务于真正目标。意志力需要值得坚持的方向。',
      '韦特亲自指出斯芬克斯的前人来源：利维。在这里，我们能辨认一次具体借鉴，而不必编造遥远起源。', true),
  },
  'major-08': {
    en: story('The old virtue of Fortitude becomes a quiet encounter between a woman and a lion.',
      'Strength belongs to the historical family of virtues represented in tarot. Fortitude was already a familiar moral subject in European art, and a lion could give courage a visible adversary or companion. Earlier tarot images do not all use the same action: the relationship between person and beast can look forceful or gentle. This variety matters because the card’s present association with compassionate self-control is an interpretation developed through particular pictures, not the only possible meaning of the virtue.',
      'Smith shows a woman handling the lion’s jaws without a weapon. Waite emphasizes that the animal has already been subdued and describes a floral chain. He also states that he exchanged this card’s position with Justice, putting Strength at VIII. He does not explain his full reason there. The numbering difference is therefore a real feature of deck history, rather than an error that must be corrected whenever another tradition places Strength at XI.',
      [['The gentle hands', 'The hands are near the lion’s mouth, making the encounter intimate and potentially dangerous. The woman’s calm posture changes the drama from conquest by force to a more controlled relationship. The picture asks how firmness and gentleness might coexist.'], ['The flowers', 'Flowers replace the harsher equipment one might expect around a dangerous animal. Waite gives them a religious interpretation involving an inwardly accepted law. A modern reading can notice how the scene represents restraint without making restraint look like punishment.'], ['The sign overhead', 'The looping form echoes the sign above the Magician. The repeated visual element links two very different images of power: one arranging tools, the other meeting a living creature. Repetition invites comparison without erasing their differences.']],
      'Modern readings commonly use Strength to discuss patience, courage, and responding to strong emotions without being ruled by them. The historical virtue gives that reading depth: courage need not be loud, and gentleness need not mean surrender. It is also important not to turn the image into a demand that someone calmly endure mistreatment. The useful question is what kind of response protects both dignity and necessary boundaries.',
      'Strength is VIII here and XI in many other decks. The difference belongs to distinct traditions of ordering, not to a universally agreed sequence.'),
    'zh-CN': story('古老的坚忍美德，成为女人与狮子之间安静的相遇。',
      '力量属于塔罗中历史悠久的美德题材。坚忍在欧洲艺术中本来就很常见，狮子则让勇气拥有可见的对手或伙伴。较早图像不一定采用同一动作：人与兽的关系可以强硬，也可以温和。因此，今天常见的“以慈悲自持”来自特定图像的发展，而不是这种美德唯一可能的意义。',
      '史密斯画出一个没有武器、双手接近狮口的女人。韦特强调狮子已经被驯服，并提到花朵构成的链条。他也说明自己把力量与正义交换位置，使力量成为第八号，但在该处没有完整解释原因。因此，编号差异是牌组历史的一部分，并不是其他传统把力量放在十一号就画错了。',
      [['温柔的双手', '双手贴近狮口，让相遇既亲密又可能危险。平静姿态使场景从武力征服转向有节制的关系，追问坚定与温柔能否同时存在。'], ['花朵', '危险动物身边出现花朵，而非严厉装备。韦特赋予它们内心接受法则的宗教解释；现代观看者则能注意到，约束没有被画成惩罚。'], ['头顶符号', '环形符号呼应魔术师头顶的图案，把安排工具与面对生命这两种不同力量联系起来。重复邀请比较，却没有抹去差异。']],
      '今天，力量常谈耐心、勇气，以及不被强烈情绪支配的回应方式。美德的历史赋予这种理解厚度：勇敢不必喧哗，温柔也不等于投降。同时，不应借这幅画要求任何人平静忍受伤害。值得问的是，怎样的回应能保护尊严与必要界限。',
      '本牌组的力量是八号，许多其他牌组则是十一号。这反映了不同排列传统，而不是唯一顺序下的对错。', true),
  },
};

// Individual closing observations connect each historical image to an approachable reading.
const reflections: Record<string, [string, string]> = {
  'major-00': [
    'Look at how much empty sky surrounds the traveler. The open space lets anticipation dominate the scene, while the small patch of ground keeps danger present. That balance is more interesting than either pure optimism or a warning against adventure. The Fool has not yet acquired the equipment, rank, or ceremonial setting of many other trumps. In a modern reading, that absence can make room for an honest admission: being new to something is a condition from which learning begins, not an identity that must be hidden or defended.',
    '看看旅人周围多么开阔的天空：期待占据了画面，小块地面又保留危险。这种平衡比单纯乐观或反对冒险更有趣。愚者尚未获得其他王牌的装备、身份与仪式环境。今天可以把这些缺席看作承认事实的空间：初来乍到是学习的起点，不是必须掩饰或维护的身份。'],
  'major-01': [
    'The table is a useful counterweight to the dramatic raised arm. Whatever lofty meaning the gesture receives, objects still have to be arranged on a surface within reach. This gives the image an unexpectedly practical character. It can prompt a person to name the actual tools, knowledge, time, and collaborators available for a task. The performer’s older ambiguity also remains valuable: presentation can make competence visible, but it can conceal a lack of preparation. The difference becomes clear when the gesture is followed by work that can be observed.',
    '桌子为高举手臂的戏剧性提供现实平衡。无论手势多么崇高，物件仍须放在够得着的表面上。这使图像出人意料地实际：可以列出真正拥有的工具、知识、时间与伙伴。表演者的旧有暧昧也仍有用，表现既能展示能力，也能遮住准备不足；后续可见的工作会让差别清楚。'],
  'major-02': [
    'The Priestess looks outward, but her surroundings do not open fully to the viewer. That combination gives the encounter a distinctive courtesy: presence is offered without complete disclosure. A modern reflection might concern the right to keep something private, or the patience needed to understand a difficult subject. Not every unanswered question is a deception. Equally, a secretive atmosphere does not make an assertion true. The card becomes more useful when it helps separate respectful attention from the wish to turn missing information into a story that already feels satisfying.',
    '女祭司面向外界，周围却没有完全向观众敞开。这种组合像一种独特的礼貌：她在场，却不必全部披露。今天可以由此思考保留隐私的权利，或理解困难课题所需的耐心。没有答案不一定是欺骗，神秘气氛也不让说法自动真实。尊重地观察，与把缺失资讯编成令人满意的故事，应当区分。'],
  'major-03': [
    'The seated posture does not make the Empress’s world inactive. Plants are ripening, water is moving, and the landscape supplies what the figure does not visibly manufacture. This can lead to a different understanding of productivity: some work consists of providing conditions in which growth can happen. Rest, nourishment, attention, and resources may be part of that work. The image also invites a question about reciprocity. If you are always asked to nourish others, what sustains the person doing the caring, and who helps preserve the conditions on which everyone depends?',
    '坐姿不等于皇后的世界停滞。植物成熟，水流前进，风景供应了她没有亲手制造的东西。这让生产力有另一种理解：有些工作是提供让成长发生的条件，包括休息、滋养、注意与资源。图像也邀请互惠的问题：若总被要求照顾别人，照顾者由谁支持？大家共同依赖的条件又由谁维护？'],
  'major-04': [
    'Compare the Emperor’s fixed frontal pose with the Fool’s unfinished step. One image organizes space around an established position; the other opens toward an uncertain next move. Neither is a complete model for every situation. A useful structure gives an experiment enough safety to begin, while curiosity can prevent structure from becoming an end in itself. Seeing the cards together turns a rigid personality label into a relationship between needs. The question becomes how much order a particular task requires, who maintains it, and when the arrangement deserves to be reconsidered.',
    '把皇帝固定的正面坐姿与愚者尚未完成的一步相比：一个围绕已确立的位置组织空间，另一个朝向未知。两者都不是所有情境的完整答案。结构能给尝试提供安全，好奇也能防止结构变成目的本身。把牌一起看，性格标签便成为不同需要的关系：任务需要多少秩序、由谁维护，又何时应重新考虑？'],
  'major-05': [
    'The attendants matter because knowledge is not preserved by a teacher alone. Someone must receive it, practice it, question it, and carry it into another setting. The card can therefore concern membership as much as leadership. What does joining a community make possible, and what does it ask you to set aside? A tradition may offer language for an experience that otherwise feels lonely, but belonging is strongest when its expectations can be understood. The historical religious scene becomes a starting point for examining how shared values are actually lived.',
    '侍者很重要，因为知识不是教师独自保存的。需要有人接受、实践、提问，再带到新环境。因此这张牌既谈领导，也谈成员身份。加入社群使什么成为可能，又要求放下什么？传统可能给孤独经验提供语言，但当共同期待能被理解时，归属才更稳固。宗教场景由此成为检查共享价值如何落实的起点。'],
  'major-06': [
    'The figures do not merge into one body. They remain separate people beneath a shared presence, with different trees behind them. That visual distinction can enrich a modern account of partnership: connection does not require identical histories, perceptions, or needs. The scene offers a way to ask what can be shared while difference is respected. It also keeps choice within relationship rather than reducing it to solitary preference. An honest decision may need conversation, consent, and an understanding of its effects on another person, not simply certainty about one’s own desire.',
    '两个人没有融合成一个身体。他们在共同存在之下仍然分开，身后树木也不同。这丰富了现代伙伴关系的理解：联系不要求完全相同的历史、感知或需要。可以问怎样在尊重差异时共享，也让选择保持在人际关系中。诚实决定可能需要交谈、同意，以及理解对别人的影响，不只是确定自己的欲望。'],
  'major-07': [
    'A striking feature of the scene is how much ceremonial readiness exists before any visible motion. Armour, canopy, vehicle, and attendants all announce capacity, but the image still leaves coordination unresolved. That is a useful distinction for practical reflection. Being equipped, being determined, and actually moving toward a goal are different states. The card can prompt a review of whether preparation has become a substitute for action, or whether action is occurring without direction. Its impressive appearance makes the quieter question of steering especially worth asking.',
    '场景特别之处在于，还没看见行动，仪式性的准备已经如此充分。铠甲、车篷、车辆与伴随生物宣示能力，协调却仍未解决。这是实际反思的重要区别：装备齐全、意志坚定与真正朝目标前进，不是同一状态。可以检查准备是否代替了行动，或行动是否缺少方向。外观越威严，越值得问谁在掌舵。'],
  'major-08': [
    'The lion is not removed from the picture. Whatever has changed, the living source of danger and vitality remains beside the woman. A contemporary reflection can use that detail to distinguish regulation from erasure. Anger, fear, or desire may need a considered response without having to be treated as proof of personal failure. The flowers and calm posture suggest a relationship that has been altered, rather than an opponent destroyed. This makes the image especially useful for considering patient practice, trusted support, and strength that does not depend on humiliating what it encounters.',
    '狮子没有从画面消失。无论关系怎样改变，危险与活力的生命来源仍在女人身边。今天可以据此区分调节与抹除：愤怒、恐惧或欲望需要审慎回应，却不必被当作个人失败。花朵与平静姿态暗示关系被改变，而不是对手被消灭。这适合思考耐心练习、可信支持，以及不靠羞辱对方建立的力量。'],
  'major-09': [
    'The lantern lights a limited area rather than the whole landscape. That smallness can be reassuring: useful knowledge need not become a claim to know everything. A person may be able to illuminate the next step for someone else while remaining uncertain about the complete route. The old association with time also gives the scene patience. Some understanding comes through returning to a subject, noticing changes, and admitting what earlier confidence overlooked. The Hermit’s light becomes more generous when experience is offered as help, rather than displayed as a reason nobody else should speak.',
    '灯照亮有限区域，而不是整片风景。这种有限反而令人安心：有用知识不必变成无所不知的主张。一个人可以照亮别人的下一步，同时仍不清楚完整路线。与时间的旧联系也赋予耐心：理解有时来自反复回来、观察变化，并承认从前自信时忽略了什么。经验若作为帮助而非压倒他人的理由，灯便更加慷慨。'],
  'major-10': [
    'A wheel brings what was above toward the side and what was below toward another position. Looking at that motion can soften the temptation to turn a temporary situation into a permanent identity. It also raises a practical question about preparation: what can be maintained when conditions change? Supportive relationships, transferable skills, and realistic commitments do not remove uncertainty, but they can change how it is met. The old image of Fortune becomes less a verdict delivered by chance and more an invitation to notice the difference between position and lasting value.',
    '轮子让上方转向侧面，也让下方进入新位置。观察运动，可以减轻把暂时状况变成永久身份的冲动。也可以问环境改变时什么仍能维持：支持关系、可迁移技能与实际承诺不能消除不确定，却能改变回应。古老命运图像因此不只像偶然宣判，而成为区分所处位置与持久价值的邀请。'],
  'major-11': [
    'The sword and scales do different jobs, and the image gives neither task entirely to the other. Careful comparison without a decision can leave a problem unresolved; decisive action without careful comparison can become arbitrary. Their pairing makes Justice useful when a situation needs both patience and a conclusion. It can also encourage examining a procedure rather than only its outcome. Were expectations clear, was relevant information considered, and could those affected respond? These questions translate the old public virtue into practices that can be checked and improved in ordinary life.',
    '剑与天平承担不同任务，不能完全互相代替。只有比较没有决定，问题可能悬而未决；只有行动没有比较，则可能武断。它们的组合适合需要耐心也需要结论的处境，还鼓励检查程序而不只看结果：期待是否清楚、资讯是否充分、受影响的人能否回应？这些问题把公共美德转成日常可检查和改进的实践。'],
  'major-12': [
    'Turning the body upside down changes the ordinary relationship between head and ground, yet the face remains composed. The image can make a familiar problem look temporarily unfamiliar. That does not require adopting the belief that every obstacle was sent for a reason. Sometimes the helpful change is modest: trying another sequence, listening to a neglected perspective, or stepping away long enough to notice an assumption. The historical transformation from a troubling posture to a contemplative one shows how strongly interpretation depends on surrounding details, not only on the outline of an action.',
    '身体倒转改变了头与地面的通常关系，脸却仍平静，使熟悉问题暂时变陌生。这不要求相信每个障碍都有安排好的理由。有时改变很小：试不同顺序、听被忽略的观点，或离开片刻以看见假设。从令人不安的姿势变成沉思图像的历史，也说明解释多么依赖周围细节，而非只靠动作轮廓。'],
  'major-13': [
    'The scene does not give everyone the same posture. People fall, look away, or face the rider, allowing several responses to coexist. That variety can be helpful when thinking about change with others: people affected by the same ending may not understand it at the same pace. The distant light does not cancel the foreground loss. Holding both parts of the composition in view permits a more humane reflection than insisting that every ending should immediately feel liberating. Continuity and mourning can occupy the same story without either making the other untrue.',
    '场景没有让所有人作同一姿势：有人倒下、有人移开目光、有人面对骑士，多种回应并存。共同经历结束的人，也未必以相同速度理解它。远处光明没有取消前景损失。同时看见两部分，比坚持每次结束都该立刻令人解脱更有人情味。延续与哀悼可以存在于同一故事，彼此不必否定。'],
  'major-14': [
    'Pouring requires an adjustment to what the vessels can actually hold. Too much speed, an unsuitable angle, or attention fixed elsewhere can undo a good intention. This ordinary physical knowledge gives the card a practical dimension beneath its mystical vocabulary. A sustainable arrangement depends on real capacities, not an ideal schedule imposed from outside. The image can prompt small experiments with timing and proportion, followed by attention to their effects. Its calm should therefore be understood as active coordination, rather than a demand to appear serene while incompatible pressures continue unchanged.',
    '倒水必须配合容器真正能容纳的量。速度过快、角度不合适或注意分散，都能使好意落空。普通身体经验给神秘术语之下的牌增添实际维度：可持续安排取决于真实能力，而非外加的理想日程。可以小幅尝试时间与比例，再观察效果。平静因此是主动协调，不是要求人在相互冲突的压力下仍装作安宁。'],
  'major-15': [
    'The central figure occupies more space than the people below, making domination visible through scale before any symbol is decoded. A modern reflection can begin there: what has become so large in your attention that other possibilities are difficult to see? The answer might involve a habit, an expectation, a relationship, or a material pressure. Those situations differ, and the same response will not suit all of them. The image becomes more useful when it leads to specific observation and appropriate support, rather than turning a complicated difficulty into a moral label.',
    '中心形象占据远多于下方人物的空间，还未解码象征，尺寸已使支配可见。可以从这里问：什么占据了太多注意，使其他可能难以看见？答案可能是习惯、期待、关系或物质压力。这些情况不同，回应不能一概而论。具体观察与适当支持，比把复杂困难变成道德标签更有用。'],
  'major-16': [
    'The tower’s height makes its fall visually dramatic, but height is not the same as a sound foundation. This is a useful distinction when an impressive explanation, reputation, or plan has acquired more confidence than its evidence can support. Revising a smaller assumption early may prevent a larger collapse later. At the same time, the falling people remind us that criticism is not complete merely because it identifies a flaw. What happens to those who relied on the structure, and what practical care will make a transition survivable, remain part of the question.',
    '塔越高，坠落越戏剧化，但高度不等于稳固基础。当解释、名声或计划获得超过证据支持的自信时，这一区别尤其有用。早些修正小假设，可能避免更大崩塌。同时，坠落人物提醒批评并非指出缺陷就完成：依赖结构的人怎么办，什么实际照料能让过渡得以承受，也属于问题。'],
  'major-17': [
    'Water is being given without an obvious transaction. There is no visible payment, command, or contest in the scene. That quality can make the Star useful for noticing forms of care that are easily undervalued because they are quiet. A restorative routine, a patient conversation, or a place where vigilance can relax may not look like a dramatic breakthrough. Yet such conditions can make further movement possible. The image’s historical language of gifts can therefore support a contemporary appreciation of receiving and replenishing, rather than treating every moment as another performance to complete.',
    '水被给予，却看不见交易、付款、命令或竞赛。这让星星适合提醒那些因安静而被低估的照料：恢复性的习惯、耐心交谈，或可以放松警戒的地方，未必像戏剧性突破，却能让后续前进成为可能。历史上关于礼物的语言，因此能支持今天对接受与补充的重视，而非把每一刻都当作待完成的表现。'],
  'major-18': [
    'The path is visible even though its destination is not. This detail offers a more patient alternative to demanding complete certainty before taking any step. One can gather a little more information, check a practical assumption, or choose a reversible action. The two animals also suggest that familiar instincts and unfamiliar reactions may be active at the same time. Instead of deciding immediately which feeling is the true message, a reflective reading can observe how each response changes when circumstances become clearer. Uncertainty can be investigated without being either worshipped or dismissed.',
    '终点不明，小路仍然可见。这提供了比“完全确定才行动”更耐心的选择：多收集一点资讯、检查实际假设，或采取可逆一步。两只动物也暗示熟悉本能与陌生反应可能同时活跃。不必马上决定哪个感受才是真正讯息，可以观察条件清楚后各反应如何变化。不确定可以被探究，而非崇拜或否定。'],
  'major-19': [
    'The child’s outstretched posture offers a contrast to the defensive equipment elsewhere in the deck. There is room here to enjoy an experience without continually proving worth or anticipating a contest. That does not require forgetting difficulty. A clear account of life can include both what hurts and what is working. The Sun can be a useful prompt to name something specific that deserves appreciation: a repaired relationship, a skill that now feels natural, or a task honestly completed. Specific gratitude gives the bright image more substance than a general instruction to stay positive.',
    '孩子伸展的姿态，与牌组其他地方的防御装备形成对照。这里可以享受经验，而不必不断证明价值或预备竞赛，也无须遗忘困难。清楚的生活叙述能同时包含痛苦与顺利。可以具体说出值得感谢的事：修复的关系、变熟练的技能，或诚实完成的任务。具体感激比泛泛要求保持积极，更能赋予明亮图像内容。'],
  'major-20': [
    'The figures rise together, which makes the scene larger than an individual achievement. A personal change may affect family, colleagues, or a community, and the recognition that prompts it may come through those relationships. The image can therefore encourage accountability without reducing change to solitary willpower. What needs to be acknowledged openly, what repair is possible, and whose response deserves attention? The trumpet’s urgency does not have to mean rushing into a dramatic declaration. Sometimes answering a clear call means making a steady commitment that remains visible in ordinary actions afterward.',
    '人物共同起身，使场景大于个人成就。个人改变可能影响家庭、同事或社群，促成认知的契机也可能来自这些关系。因此可以谈责任，而不把变化缩减为独自意志。什么需要公开承认，什么修复仍可能，谁的回应值得听？号角的迫切不必意味着仓促宣言；有时回应召唤，是在后续日常行动中维持稳定承诺。'],
  'major-21': [
    'A completion becomes easier to recognize when its boundaries are named. What belonged to this undertaking, and what was never part of it? The wreath offers a visual way to consider that distinction. Without a boundary, even meaningful progress can feel unfinished because another possible improvement is always available. Acknowledging completion does not deny future learning; it allows the work already done to become part of a larger life. The moving center keeps celebration from becoming a demand to remain forever at one perfect moment, and leaves space for another beginning to arrive.',
    '说清边界，完成才更容易被承认：哪些属于这项任务，哪些从未属于它？花环给这种区别提供视觉方式。没有边界，再有意义的进步也会因总有改进可能而显得未完。承认完成不否认未来学习，而是让已经做好的工作进入更大生活。运动的中心使庆祝不成为永久停在完美瞬间的要求，也为新开始留空间。'],
};

for (const [id, [en, zh]] of Object.entries(reflections)) {
  historyMajor[id].en.today.push(en);
  historyMajor[id]['zh-CN'].today.push(zh);
}

for (const id of ['major-01', 'major-09']) {
  historyMajor[id].en.sources.push('https://www.themorgan.org/collection/tarot-cards');
  historyMajor[id]['zh-CN'].sources.push('https://www.themorgan.org/collection/tarot-cards');
}
